INSERT INTO faqs (question, answer, sort_order) VALUES
  ('Do you guarantee profits?', 'No. Nobody can honestly guarantee profits from crypto. Prices go up and down quickly and you can lose money. Be very careful of anyone who promises fixed returns.', 0),
  ('Will you ever ask for my seed phrase or private keys?', 'Never. Anyone asking for your seed phrase, private keys or passwords is trying to steal from you.', 1),
  ('Why do you ask for ID?', 'Identity checks protect you and us, and help prevent fraud and money laundering.', 2),
  ('Is the trading on this website real?', 'Not while the site is in demo mode: the balance and trades use fake money so you can learn how buying and selling works. Live prices come from CoinGecko.', 3),
  ('Is this financial advice?', 'No. We provide education and services, not financial advice. Make your own decisions and only use money you can afford to lose.', 4),
  ('Do I need experience to join a class?', 'No. Our beginner classes start from zero.', 5);
